-- Epson Expert Connect - MySQL schema (MySQL 5.7+/8.x, MariaDB 10.3+). Idempotent: safe to re-run.
-- Ids are UUIDs generated by the app. Timestamps are stored in DB_TIMEZONE_OFFSET (default IST).
-- JSON columns hold string arrays, e.g. ["English","Hindi"].

-- Staff: admins and agents (product experts)
CREATE TABLE IF NOT EXISTS users (
  id             CHAR(36)     NOT NULL,
  name           VARCHAR(80)  NOT NULL,
  email          VARCHAR(191) NOT NULL,
  password_hash  VARCHAR(100) NOT NULL,
  role           ENUM('admin','agent') NOT NULL,
  languages      JSON         NOT NULL,
  is_active      TINYINT(1)   NOT NULL DEFAULT 1,
  last_login_at  DATETIME(3)  NULL,
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Retail stores where QR codes are placed
CREATE TABLE IF NOT EXISTS stores (
  id               CHAR(36)     NOT NULL,
  code             VARCHAR(40)  NOT NULL,
  name             VARCHAR(120) NOT NULL,
  city             VARCHAR(60)  NULL,
  state            VARCHAR(60)  NULL,
  default_product  VARCHAR(80)  NULL,
  is_active        TINYINT(1)   NOT NULL DEFAULT 1,
  created_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_stores_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Customers who filled the form after scanning a QR code
CREATE TABLE IF NOT EXISTS leads (
  id          CHAR(36)     NOT NULL,
  name        VARCHAR(60)  NOT NULL,
  mobile      VARCHAR(15)  NOT NULL,
  state       VARCHAR(60)  NOT NULL,
  city        VARCHAR(60)  NOT NULL,
  interests   JSON         NOT NULL,
  store_id    CHAR(36)     NULL,
  product     VARCHAR(80)  NULL,
  consent     TINYINT(1)   NOT NULL DEFAULT 0,
  user_agent  VARCHAR(300) NULL,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_leads_created_at (created_at),
  KEY idx_leads_mobile (mobile),
  KEY idx_leads_store (store_id),
  CONSTRAINT fk_leads_store FOREIGN KEY (store_id) REFERENCES stores (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Every call attempt from a lead
--   queued      -> waiting for an agent
--   in_progress -> agent accepted, talking
--   completed   -> call happened (agent connected), then ended
--   missed      -> nobody accepted within CALL_RING_TIMEOUT_SEC
--   cancelled   -> customer left before an agent picked up
--   failed      -> technical failure (e.g. server restart while queued)
CREATE TABLE IF NOT EXISTS calls (
  id                 CHAR(36)     NOT NULL,
  lead_id            CHAR(36)     NOT NULL,
  agent_id           CHAR(36)     NULL,
  mode               ENUM('video','voice') NOT NULL,
  language           VARCHAR(30)  NOT NULL DEFAULT 'English',
  status             ENUM('queued','in_progress','completed','missed','cancelled','failed') NOT NULL DEFAULT 'queued',
  customer_token     CHAR(48)     NOT NULL,
  requested_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  accepted_at        DATETIME(3)  NULL,
  ended_at           DATETIME(3)  NULL,
  duration_seconds   INT          NULL,
  end_reason         VARCHAR(40)  NULL,
  rating             TINYINT      NULL,
  feedback           VARCHAR(500) NULL,
  outcome            ENUM('interested','purchased','follow_up','not_interested','support','other') NULL,
  agent_notes        TEXT         NULL,
  customer_requests  JSON         NOT NULL,
  updated_at         DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_calls_status (status),
  KEY idx_calls_requested_at (requested_at),
  KEY idx_calls_agent (agent_id),
  KEY idx_calls_lead (lead_id),
  CONSTRAINT fk_calls_lead FOREIGN KEY (lead_id) REFERENCES leads (id) ON DELETE CASCADE,
  CONSTRAINT fk_calls_agent FOREIGN KEY (agent_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
